import json,sys,os
from pathlib import Path
import bpy,numpy as np
def arg(n):
 a=sys.argv[sys.argv.index('--')+1:]; return Path(a[a.index(n)+1]).resolve()
def main():
 key_name=os.environ.get('VELA_GOAL2_BROW_KEY','controlled_brow_5pct_qp'); source,solution,output,report=arg('--source'),arg('--solution'),arg('--output'),arg('--report'); z=np.load(solution); bpy.ops.wm.read_factory_settings(use_empty=True); bpy.ops.import_scene.gltf(filepath=str(source)); body=max([o for o in bpy.context.scene.objects if o.type=='MESH'],key=lambda o:len(o.data.vertices)); n=len(body.data.vertices); local=np.empty((n,3),float); body.data.vertices.foreach_get('co',local.ravel()); mw=np.asarray(body.matrix_world,float); inv=np.linalg.inv(mw[:3,:3]); d=np.zeros_like(local); d[z['local_indices']]=z['delta_world']@inv.T; body.shape_key_add(name='Basis',from_mix=False); key=body.shape_key_add(name=key_name,from_mix=False); key.data.foreach_set('co',(local+d).astype(np.float32).ravel()); key.value=0; body.data.shape_keys.use_relative=True; bpy.ops.object.select_all(action='DESELECT'); [o.select_set(True) for o in bpy.context.scene.objects if o.type in {'MESH','ARMATURE','EMPTY'}]; bpy.context.view_layer.objects.active=body; output.parent.mkdir(parents=True,exist_ok=True); bpy.ops.export_scene.gltf(filepath=str(output),export_format='GLB',export_morph=True,export_skins=True,export_animations=True,export_apply=False); report.parent.mkdir(parents=True,exist_ok=True); report.write_text(json.dumps({'shapeKey':key.name,'source':str(source),'solution':str(solution),'constraintResidual':z['constraint_residual'].tolist()},indent=2)+'\n')
if __name__=='__main__': main()
